/**
 * P7 (D-154): docs/P7_BEFORE_AFTER.md and docs/P7_LABOUR_PROVENANCE.md (generated by
 * scripts/p5b/build-goods-1900.mjs from calibration_1900.json `p7`).
 */
const fmt = (value, digits = 1) => (value === null || value === undefined || !Number.isFinite(value) ? "–" : value.toFixed(digits));
const pct = (value, digits = 1) => (value === null || value === undefined || !Number.isFinite(value) ? "–" : `${(value * 100).toFixed(digits)} %`);
const millions = (value) => (value / 1e6).toFixed(2);
const sum = (values) => values.reduce((acc, value) => acc + value, 0);

const COUNTRY_ROWS = ["usa-home", "gbr-home", "deu-home", "fra-home", "rus-home", "ita-home", "aut-home", "jpn-home", "chn-home", "bin", "esp-home", "bra-home", "mex-home", "ott-home", "dei", "egy"];

export function p7BeforeAfterReport(trace) {
  const lines = [];
  const professions = trace.professions.map((profession) => profession.key);
  const worldBefore = sum(Object.values(trace.before.world));
  const worldAfter = sum(Object.values(trace.after.world));
  lines.push("# P7 before and after — the 1900 labour market");
  lines.push("");
  lines.push("Generated by `scripts/p5b/build-goods-1900.mjs` (P7 steps in `scripts/p7/`) from");
  lines.push("`packages/data/data/historical/p5b/calibration_1900.json` (`p7`). Before = the P6 world (five");
  lines.push("professions, estimated incomes); after = the P7 world (sixteen professions, sourced occupation");
  lines.push("shares, day-1 employment and measured incomes). Day-1 employment is the generator's rule");
  lines.push("(own province, full staffing, institution posts = budget ÷ wage); the simulation's first refresh");
  lines.push("applies the same rule.");
  lines.push("");
  lines.push(`Blocks: ${trace.blocks.before.toLocaleString("en-US")} before, ${trace.blocks.after.toLocaleString("en-US")} after. Building owners changed: ${String(trace.ownersChanged)}. Incomes (plan Q18, designer's decision 2026-11-09, "one pass, measure once"): demand and placement use the P6 estimate (wage × participation × working-age share, here over the sixteen professions); the blocks' opening incomes are then measured once from day-1 employment and owner profits. The estimate column shows what placement assumed, the measured column what the blocks receive on day 1.`);
  lines.push("");
  lines.push("## World population by profession (millions)");
  lines.push("");
  lines.push("| Profession | Before | After | Share after | Day-1 eligible | Day-1 offered | Day-1 employed | Unemployment |");
  lines.push("|---|---:|---:|---:|---:|---:|---:|---:|");
  const totals = (field) => {
    const out = {};
    for (const row of Object.values(trace.after.byTerritory)) for (const [key, value] of Object.entries(row[field])) out[key] = (out[key] ?? 0) + value;
    return out;
  };
  const eligible = totals("eligible");
  const offered = totals("offered");
  const employed = totals("employed");
  for (const key of professions) {
    const after = trace.after.world[key] ?? 0;
    const before = trace.before.world[key] ?? 0;
    const e = eligible[key] ?? 0;
    lines.push(`| ${key} | ${before > 0 ? millions(before) : "–"} | ${after > 0 ? millions(after) : "–"} | ${pct(after / worldAfter)} | ${millions(e)} | ${millions(offered[key] ?? 0)} | ${millions(employed[key] ?? 0)} | ${e > 0 ? pct(1 - (employed[key] ?? 0) / e) : "–"} |`);
  }
  const eAll = sum(Object.values(eligible));
  const empAll = sum(Object.values(employed));
  lines.push(`| **all** | ${millions(worldBefore)} | ${millions(worldAfter)} | 100 % | ${millions(eAll)} | ${millions(sum(Object.values(offered)))} | ${millions(empAll)} | ${pct(1 - empAll / eAll)} |`);
  lines.push("");
  lines.push("## Countries");
  lines.push("");
  lines.push("Income per person (RUSD a year): before = the P6 world's estimate (five professions); estimate = the same rule over the sixteen professions (what placement used); measured = day-1 wages + owner profits (the blocks' opening income). Unemployment = 1 − employed ÷ eligible over all professions.");
  lines.push("");
  lines.push("| Territory | Source of shares | Peasants | Farmers | Laborers | Attendants | Shopkeepers | Clerks | Professionals* | Income before | Estimate | Measured | Unemployment |");
  lines.push("|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
  for (const key of COUNTRY_ROWS) {
    const after = trace.after.byTerritory[key];
    const before = trace.before.byTerritory[key];
    if (after === undefined || before === undefined) continue;
    const share = (profession) => pct((after.persons[profession] ?? 0) / after.population);
    const professional = ["teachers", "medics", "engineers", "academics", "bureaucrats"].reduce((acc, profession) => acc + (after.persons[profession] ?? 0), 0) / after.population;
    const e = sum(Object.values(after.eligible));
    const emp = sum(Object.values(after.employed));
    const method = (trace.shares[key]?.method ?? "").startsWith("census") ? trace.shares[key].method.split(";")[0] : "proxy";
    lines.push(`| ${key} | ${method} | ${share("peasants")} | ${share("farmers")} | ${share("laborers")} | ${share("attendants")} | ${share("shopkeepers")} | ${share("clerks")} | ${pct(professional)} | ${fmt(before.incomeRUSDPerYear / before.population, 0)} | ${fmt((after.estimateRUSDPerYear ?? 0) / after.population, 0)} | ${fmt(after.incomeRUSDPerYear / after.population, 0)} | ${e > 0 ? pct(1 - emp / e) : "–"} |`);
  }
  lines.push("");
  lines.push("\\* teachers, medics, engineers, academics and bureaucrats.");
  lines.push("");
  lines.push("## Institutions (plan Q3, Q4)");
  lines.push("");
  const fs = trace.institutionFunctionShares;
  lines.push(`Posts are funded by the sourced budgets (P2b/P5b shares of covered value added); the policy splits each pool by function shares (R9): health ${pct(fs.healthOfAdministration)} of administration and research ${pct(fs.researchOfEducation)} of education (US all governments 1902, HSUS series Y 533-566), training ${pct(fs.trainingOfEducation)} of education (provisional).`);
  lines.push("");
  lines.push("| Country | Health share of administration | Research share of education | Training budget (RUSD a year) | Education budget left (RUSD a year) |");
  lines.push("|---|---:|---:|---:|---:|");
  for (const tag of ["USA", "GBR", "DEU", "FRA", "RUS", "JPN", "ITA", "AUT", "CHN"]) {
    const row = trace.institutions[tag];
    if (row === undefined) continue;
    lines.push(`| ${tag} | ${pct(row.healthStaffShare)} | ${pct(row.researchStaffShare)} | ${fmt(row.trainingBudgetRUSDPerYear, 0)} | ${fmt(row.educationFundingRUSDPerYear, 0)} |`);
  }
  lines.push("");
  lines.push("## Interim placement (plan Q2a)");
  lines.push("");
  lines.push("Census servicemen, officers and clergy are counted in laborers, bureaucrats and academics until their stages populate them.");
  lines.push("");
  lines.push("| Territory | Servicemen | Officers | Clergy |");
  lines.push("|---|---:|---:|---:|");
  for (const [key, entry] of Object.entries(trace.shares)) {
    if (entry.interim === null) continue;
    lines.push(`| ${key} | ${Math.round(entry.interim.servicemen).toLocaleString("en-US")} | ${Math.round(entry.interim.officers).toLocaleString("en-US")} | ${Math.round(entry.interim.clergy).toLocaleString("en-US")} |`);
  }
  lines.push("");
  return `${lines.join("\n")}\n`;
}

export function p7Provenance(trace, sources) {
  const lines = [];
  lines.push("# P7 labour provenance");
  lines.push("");
  lines.push("Generated by `scripts/p5b/build-goods-1900.mjs` (P7 steps in `scripts/p7/`). Every P7 value of the 1900");
  lines.push("world traces to a row of `packages/data/data/historical/p7/sources_1900.json` (written by");
  lines.push("`scripts/p7/sources-author.mjs`) or is a named provisional constant of `scripts/p7/labour.mjs` /");
  lines.push("`scripts/p7/labour-build.mjs`.");
  lines.push("");
  lines.push("## Sources, licences and attribution");
  lines.push("");
  lines.push("| Id | Title | Licence | Attribution |");
  lines.push("|---|---|---|---|");
  for (const source of sources.sources) lines.push(`| ${source.id} | ${source.title} (${source.url}) | ${source.license} | ${source.attribution} |`);
  lines.push("");
  lines.push("## Professions and 1900 reference wages (United States)");
  lines.push("");
  lines.push("| Id | Profession | Roles | Gates | Settlement | Participation | Wage (RUSD a year) | Ratio to laborer | Rows |");
  lines.push("|---:|---|---|---|---|---:|---:|---:|---|");
  for (const profession of trace.professions) {
    lines.push(`| ${String(profession.id)} | ${profession.key} | ${profession.roles.join(", ")} | ${profession.gates.join(", ") || "–"} | ${profession.settlement} | ${fmt(profession.participationRate, 2)} | ${fmt(profession.baseWage1900RUSDPerYear, 0)} | ${fmt(profession.wageRatioToLaborer, 3)} | ${profession.wageRows.join(", ")} |`);
  }
  lines.push("");
  lines.push("## Occupation shares by territory");
  lines.push("");
  lines.push("| Territory | Method | Rows |");
  lines.push("|---|---|---|");
  for (const [key, entry] of Object.entries(trace.shares)) {
    if (!entry.method.startsWith("census")) continue;
    lines.push(`| ${key} | ${entry.method} | ${entry.rows.length} rows${entry.notes.length > 0 ? `; ${entry.notes.join("; ")}` : ""} |`);
  }
  const proxies = Object.entries(trace.shares).filter(([, entry]) => !entry.method.startsWith("census")).map(([key]) => key);
  lines.push("");
  lines.push(`Proxy territories (${String(proxies.length)}; least squares of each share on 1, ln GDP per head and urban share over the sourced territories, clamped at 0 and renormalised; P7 provisional): ${proxies.join(", ")}.`);
  lines.push("");
  lines.push("## Provisional rows");
  lines.push("");
  lines.push("| Id | Measure | Value | Reasoning |");
  lines.push("|---|---|---:|---|");
  for (const row of sources.provisionalRows) lines.push(`| ${row.id} | ${row.measure} | ${String(row.value)} | ${row.note} |`);
  lines.push("");
  return `${lines.join("\n")}\n`;
}
